const listDeployments = `-- name: ListDeployments :many
SELECT id, environment_id, desired_revision_id, previous_healthy_revision_id, task_run_id, idempotency_key, status, requested_by, confirmed_by, created_at, updated_at, finished_at, health_passed, rollback_of_id, failure_code, fence_required FROM deployments WHERE $1::text='' OR environment_id=$1 ORDER BY created_at DESC
`

func (q *Queries) ListDeployments(ctx context.Context, environmentID string) ([]Deployment, error) {
	rows, err := q.db.Query(ctx, listDeployments, environmentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Deployment{}
	for rows.Next() {
		var i Deployment
		if err := rows.Scan(
			&i.ID,
			&i.EnvironmentID,
			&i.DesiredRevisionID,
			&i.PreviousHealthyRevisionID,
			&i.TaskRunID,
			&i.IdempotencyKey,
			&i.Status,
			&i.RequestedBy,
			&i.ConfirmedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.FinishedAt,
			&i.HealthPassed,
			&i.RollbackOfID,
			&i.FailureCode,
			&i.FenceRequired,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

